/**
 * A thin client for the Smira API.
 *
 * The deployed API is the default so a build with nothing configured still
 * reaches it; NEXT_PUBLIC_API_URL points it somewhere else. Most of the site
 * runs on its own content — the one thing that genuinely has to reach the
 * desk is a partner application.
 */

const BASE = (process.env.NEXT_PUBLIC_API_URL || 'https://smiraclubbackend.vercel.app/api').replace(/\/$/, '');

class ApiError extends Error {
  constructor(status, message, details) {
    super(message);
    this.status = status;
    this.details = details;
  }
}

async function request(path, { method = 'GET', body, token, next } = {}) {
  if (!BASE) throw new ApiError(0, 'NEXT_PUBLIC_API_URL is not set');

  const res = await fetch(`${BASE}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
    },
    body: body ? JSON.stringify(body) : undefined,
    // Only a GET is worth caching; a submission has to go every time.
    ...(method === 'GET' ? { next: next || { revalidate: 60 } } : { cache: 'no-store' }),
  });

  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new ApiError(res.status, json.message || 'That request did not work', json.details);
  return json;
}

export const api = {
  /** Whether the site has somewhere to ask. */
  get isConfigured() {
    return Boolean(BASE);
  },

  /**
   * What the desk is selling, from Travel Inventory on the admin panel —
   * hotels, villas, restaurants, spas, activities, packages and the rest.
   * Anything the desk adds there reaches the site without a deploy.
   */
  catalog: (query = '') => request(`/website/catalog${query}`, { next: { revalidate: 60 } }),
  catalogItem: (id) => request(`/website/catalog/${encodeURIComponent(id)}`, { next: { revalidate: 60 } }),

  /**
   * What somebody told the membership quiz.
   *
   * Sent once they have finished it, so the desk has the answers whether
   * or not they go on to buy. It never blocks the page: a failure here
   * costs the desk a lead, not the member their result.
   */
  tellQuiz: (body) => request('/website/quiz', { method: 'POST', body }),

  /**
   * Is this coupon any good, and what is it worth on this spend?
   *
   * Never cached: a code can run out between one person typing it and the
   * next, and the answer carries a price.
   */
  checkCoupon: (code, spend, forWhat = 'Membership') =>
    request(
      `/website/coupon/${encodeURIComponent(String(code).trim().toUpperCase())}` +
        `?spend=${Math.round(spend || 0)}&for=${forWhat}`,
      { next: { revalidate: 0 } },
    ),

  /** The offers the desk has put live on the panel's Offers page. */
  deskOffers: () => request('/website/offers', { next: { revalidate: 60 } }),

  /**
   * The blog the desk writes in the admin panel.
   *
   * Short revalidate: somebody publishes a post and then goes to look at
   * it, and five minutes of an empty page is read as it not having worked.
   */
  blogs: () => request('/website/blogs', { next: { revalidate: 30 } }),

  /** The Grab Offers strip the desk arranges in the panel. */
  homeOffers: () => request('/website/home-offers', { next: { revalidate: 30 } }),
  blogPost: (slug) =>
    request(`/website/blogs/${encodeURIComponent(slug)}`, { next: { revalidate: 30 } }),
  /** A complaint from Get Help; it opens a ticket on the support desk. */
  raiseComplaint: (form) =>
    request('/website/support', { method: 'POST', body: form, next: { revalidate: 0 } }),
  /** The short ones, with the listing and the clock on them. Kept fresher
      than the rest: an offer with an hour left is worth half a minute. */
  deskFlashOffers: () => request('/website/offers/flash', { next: { revalidate: 30 } }),

  /**
   * Any other service asked for on the site — a trip planned, a visa,
   * insurance, forex. It lands in the admin panel's Sales & Leads as a new
   * lead, tagged by service, with every answer on the form written onto it.
   */
  enquiry: (form) =>
    request('/website/enquiry', { method: 'POST', body: form, next: { revalidate: 0 } }),

  /**
   * A property owner applying from the Become a Partner page. It lands in the
   * admin panel's partner onboarding as a registration waiting on papers.
   */
  applyAsPartner: (form) =>
    request('/partners/apply', { method: 'POST', body: form, next: { revalidate: 0 } }),

  /**
   * A customised international tour asked for from International Trips. It
   * lands in the admin panel's Sales & Leads as a new lead, with every answer
   * on the form written onto it.
   */
  tripEnquiry: (form) =>
    request('/website/trip-enquiry', { method: 'POST', body: form, next: { revalidate: 0 } }),

  /**
   * A fixed-departure package booked from its page. It lands on the admin
   * panel's Booking page as a pending booking for the desk to confirm.
   */
  packageBooking: (form) =>
    request('/website/package-booking', { method: 'POST', body: form, next: { revalidate: 0 } }),

  /**
   * Any other booking made on the website — hotel, villa, free stay, table,
   * park, spa and the rest. It lands on the Booking page as pending and in
   * Sales & Leads as a new lead.
   */
  websiteBooking: (form) =>
    request('/website/booking', { method: 'POST', body: form, next: { revalidate: 0 } }),

  /**
   * A document from somebody applying to be a partner — a scan of a lease,
   * a photograph of a cancelled cheque. Nobody is signed in at this point,
   * so the route that takes it is capped hard.
   */
  uploadPartnerDocument: (body) =>
    request('/uploads/apply', { method: 'POST', body, next: { revalidate: 0 } }),

  /**
   * Somebody opened a listing. It is a tally for the partner's Performance
   * page, so it is sent and forgotten — the reply carries nothing.
   */
  countListingView: (id) =>
    request(`/website/catalog/${encodeURIComponent(id)}/view`, { method: 'POST', next: { revalidate: 0 } }),

  /**
   * A membership bought on the membership page. It lands on the admin
   * panel's Members page as new, payment pending, for the desk to activate.
   */
  /**
   * Signing in with a mobile number: ask for the code, then prove it. What
   * comes back is the member's own details and membership, so they can pick
   * up on any device.
   */
  memberOtpRequest: (phone) =>
    request('/website/member/otp', { method: 'POST', body: { phone }, next: { revalidate: 0 } }),
  memberVerify: (phone, code) =>
    request('/website/member/verify', { method: 'POST', body: { phone, code }, next: { revalidate: 0 } }),

  /**
   * The member's wishlist, kept against their account rather than the
   * browser. `merge` carries whatever they saved before signing in.
   */
  wishlistRead: (token) => request('/website/member/wishlist', { token, next: { revalidate: 0 } }),

  /**
   * The member's own gifts and referrals.
   *
   * Both screens drew a list written into the site and claimed gifts in
   * the browser, so the desk never heard about either. These are the
   * member's actual rows, read from their token.
   */
  memberRewards: (token) => request('/website/member/rewards', { token, next: { revalidate: 0 } }),

  /**
   * What is happening on this member's account.
   *
   * Nothing stores a notification: the server works them out from the
   * bookings, membership, gifts and offers each time, so they are never
   * cached.
   */
  /** What the membership and our offers have taken off their bookings. */
  memberSavings: (token) => request('/website/member/savings', { token, next: { revalidate: 0 } }),

  memberNotifications: (token) =>
    request('/website/member/notifications', { token, next: { revalidate: 0 } }),
  readNotifications: (token) =>
    request('/website/member/notifications/read', { method: 'POST', token }),
  claimReward: (token, id) =>
    request(`/website/member/rewards/${encodeURIComponent(id)}/claim`, { method: 'POST', token }),
  memberReferrals: (token) => request('/website/member/referrals', { token, next: { revalidate: 0 } }),
  referSomeone: (token, body) => request('/website/member/refer', { method: 'POST', token, body }),
  wishlistWrite: (token, body) =>
    request('/website/member/wishlist', { method: 'POST', token, body, next: { revalidate: 0 } }),

  /** The signed-in member's own details, membership and bookings. */
  memberMe: (token) => request('/website/member/me', { token, next: { revalidate: 0 } }),

  /** The membership plans as set up on the admin panel's Plans page. */
  websitePlans: () => request('/website/plans', { next: { revalidate: 60 } }),

  joinMembership: (form) =>
    request('/website/membership', { method: 'POST', body: form, next: { revalidate: 0 } }),

  login: (email, password) => request('/auth/login', { method: 'POST', body: { email, password } }),
  me: (token) => request('/auth/me', { token }),
};

export { ApiError };
